#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_H 50
#define MAX_W 50

int H, W;
char grid[MAX_H][MAX_W + 1];
int dist[MAX_H][MAX_W];

int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};

int bfs() {
    // Initialize distances with -1
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            dist[i][j] = -1;
        }
    }

    // Queue for BFS (using simple array as queue)
    int queue_x[MAX_H * MAX_W];
    int queue_y[MAX_H * MAX_W];
    int front = 0, rear = 0;

    // Start from (0, 0)
    dist[0][0] = 0;
    queue_x[rear] = 0;
    queue_y[rear] = 0;
    rear++;

    while (front < rear) {
        int x = queue_x[front];
        int y = queue_y[front];
        front++;

        // If we reached destination, return distance
        if (x == H - 1 && y == W - 1) {
            return dist[x][y];
        }

        // Try all 4 directions
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            // Check bounds and if it's a white square and not visited
            if (nx >= 0 && nx < H && ny >= 0 && ny < W && 
                grid[nx][ny] == '.' && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                queue_x[rear] = nx;
                queue_y[rear] = ny;
                rear++;
            }
        }
    }

    // Destination not reachable
    return -1;
}

int main() {
    scanf("%d %d", &H, &W);

    int white_count = 0;
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '.') {
                white_count++;
            }
        }
    }

    // Check if start or end is black
    if (grid[0][0] == '#' || grid[H-1][W-1] == '#') {
        printf("-1\n");
        return 0;
    }

    int shortest_path = bfs();

    if (shortest_path == -1) {
        printf("-1\n");
    } else {
        // Maximum changes = total white squares - shortest path length - 1
        // (we keep the white squares on the shortest path, excluding start)
        // Actually: total whites - (shortest_path + 1) = whites not on path
        // But we can't change start and end, so subtract 2 from path squares
        // Formula: white_count - (shortest_path + 1)
        // Because path has shortest_path+1 squares (including start and end)
        printf("%d\n", white_count - (shortest_path + 1));
    }

    return 0;
}

