#define MAXH 55
#define MAXW 55
#define INF 1000000000

typedef struct {
    int r, c;
} Node;

char grid[MAXH][MAXW + 1];
int dista[MAXH][MAXW];
Node queue[MAXH * MAXW];

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    int white = 0;
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '.') white++;
            dista[i][j] = INF;
        }
    }

    int head = 0, tail = 0;
    if (grid[0][0] == '.' && grid[H - 1][W - 1] == '.') {
        dista[0][0] = 1;  // number of cells on the path
        queue[tail++] = (Node){0, 0};
    }

    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};

    while (head < tail) {
        Node cur = queue[head++];
        for (int k = 0; k < 4; k++) {
            int nr = cur.r + dr[k];
            int nc = cur.c + dc[k];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            if (grid[nr][nc] != '.') continue;
            if (dista[nr][nc] > dista[cur.r][cur.c] + 1) {
                dista[nr][nc] = dista[cur.r][cur.c] + 1;
                queue[tail++] = (Node){nr, nc};
            }
        }
    }

    if (dista[H - 1][W - 1] == INF) {
        printf("-1\n");
    } else {
        printf("%d\n", white - dista[H - 1][W - 1]);
    }

    return 0;
}

