public class Main {
    static final int INF = Integer.MAX_VALUE / 2;
    static int H, W;
    static char[][] grid;
    static int[][] dist;
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = sc.next().toCharArray();
        }
        sc.close();

        // If start or end is black, impossible
        if (grid[0][0] == '#' || grid[H-1][W-1] == '#') {
            System.out.println(-1);
            return;
        }

        // Count white cells
        int whiteCount = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == '.') whiteCount++;
            }
        }

        // BFS to find shortest path length in terms of steps
        dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, INF);
        dist[0][0] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < H && ny >= 0 && ny < W 
                    && grid[nx][ny] == '.' && dist[nx][ny] == INF) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }

        // If no path exists
        if (dist[H-1][W-1] == INF) {
            System.out.println(-1);
            return;
        }

        // Maximum changes = total white cells - (shortest path length + 1)
        // Because we must keep at least the cells on one shortest path white
        int answer = whiteCount - (dist[H-1][W-1] + 1);
        System.out.println(answer);
    }
}

