public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] grid = new char[H][];
        int whiteCount = 0;
        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == '.') whiteCount++;
            }
        }

        int[][] dist = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(dist[i], -1);

        ArrayDeque<int[]> q = new ArrayDeque<>();
        if (grid[0][0] == '.') {
            dist[0][0] = 1; // number of cells used in the path
            q.add(new int[]{0, 0});
        }

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;
                if (dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[r][c] + 1;
                q.add(new int[]{nr, nc});
            }
        }

        if (dist[H - 1][W - 1] == -1) {
            System.out.println(-1);
        } else {
            System.out.println(whiteCount - dist[H - 1][W - 1]);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import sys
from collections import deque

def main():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    white_count = sum(row.count('.') for row in grid)

    INF = 10**18
    dist = [[INF] * W for _ in range(H)]
    q = deque()

    if grid[0][0] == '.':
        dist[0][0] = 1  # number of cells in the path
        q.append((0, 0))

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while q:
        x, y = q.popleft()
        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W:
                if grid[nx][ny] == '.' and dist[nx][ny] == INF:
                    dist[nx][ny] = dist[x][y] + 1
                    q.append((nx, ny))

    if dist[H - 1][W - 1] == INF:
        print(-1)
    else:
        # Keep only one shortest white path; paint all other white cells black
        print(white_count - dist[H - 1][W - 1])

